<span class="eyebrow"><?= $mode==='register'?'A LITTLE CURIOUS? YOU’RE IN THE RIGHT PLACE.':($mode==='login'?'YOUR NEXT CHAPTER IS WAITING.':'LET’S GET YOU BACK TO LEARNING.') ?></span>
<h1><?= $mode==='register'?'Big things start small.':($mode==='login'?'Good to have you back.':($mode==='forgot'?'A fresh start.':'Make it memorable.')) ?></h1>
<p class="auth-description"><?= match($mode){'register'=>'Create your free account. Choose a skill. See where a little learning takes you.','forgot'=>'Enter your email and we’ll help you reset your password when email delivery is configured.','reset'=>'Choose a strong, unique password. Your other sign-in sessions will be securely closed.',default=>'Pick up where you left off. Your future self will thank you.'} ?></p>
<form action="<?= e(route_url('/api/auth/' . (match($mode){'register'=>'register','forgot'=>'forgot','reset'=>'reset',default=>'login'}))) ?>" method="post" data-api>
<?= csrfField() ?><div class="form-error" role="alert"></div>
<?php if($mode==='register'): ?><div class="field"><label for="full-name">Your full name</label><input id="full-name" name="full_name" autocomplete="name" placeholder="What should we call you?" required minlength="2" maxlength="120"></div><?php endif; ?>
<?php if($mode!=='reset'): ?><div class="field"><label for="email">Email address</label><div class="input-wrap input-icon"><?= icon('mail',16) ?><input id="email" type="email" name="email" autocomplete="email" placeholder="you@example.com" required maxlength="190"></div></div><?php endif; ?>
<?php if($mode!=='forgot'): ?><div class="field"><label for="password"><?= $mode==='reset'?'New password':'Password' ?></label><div class="input-wrap"><input id="password" type="password" name="password" autocomplete="<?= $mode==='login'?'current-password':'new-password' ?>" placeholder="<?= $mode==='login'?'Your password':'A memorable, 12+ character passphrase' ?>" required <?= $mode!=='login'?'minlength="12" maxlength="128"':'' ?>><button type="button" data-toggle-password="password" aria-label="Show password" aria-pressed="false"><?= icon('eye',17) ?></button></div><?php if($mode!=='login'): ?><span class="field-help">At least 12 characters. Longer is stronger.</span><?php endif; ?></div><?php endif; ?>
<?php if(in_array($mode,['register','reset'],true)): ?><div class="field"><label for="password-confirmation">Confirm your password</label><div class="input-wrap"><input id="password-confirmation" type="password" name="password_confirmation" autocomplete="new-password" placeholder="One more time, just to be sure" required minlength="12" maxlength="128"><button type="button" data-toggle-password="password-confirmation" aria-label="Show password confirmation"><?= icon('eye',17) ?></button></div></div><?php endif; ?>
<?php if($mode==='login'): ?><div class="auth-inline-links"><span><?= icon('shield',13) ?> A secure learning space</span><a href="<?= e(route_url('/forgot-password')) ?>">Forgot your password?</a></div><?php endif; ?>
<?php if($mode==='register'): ?><label class="checkbox-label"><input type="checkbox" name="terms" value="1" required><span>I agree to the <a href="<?= e(route_url('/terms')) ?>" target="_blank" rel="noopener">Terms of Service</a> and <a href="<?= e(route_url('/privacy')) ?>" target="_blank" rel="noopener">Privacy Policy</a>.</span></label><?php if(!empty($_GET['ref'])): ?><input type="hidden" name="referral_code" value="<?= e(mb_substr((string)$_GET['ref'],0,20)) ?>"><p class="fine-print" style="margin-bottom:16px"><?= icon('gift',13) ?> You’re starting with a friend’s invitation.</p><?php endif; endif; ?>
<?php if($mode==='reset'): ?><input type="hidden" name="token" value="<?= e(mb_substr((string)($_GET['token']??''),0,64)) ?>"><?php endif; ?>
<button class="btn btn-primary btn-block" type="submit"><?= match($mode){'register'=>'Create my free account','forgot'=>'Send reset instructions','reset'=>'Save my new password',default=>'Let’s keep learning'} ?> <?= icon('arrow-right',17) ?></button>
</form>
<p class="auth-bottom"><?php if($mode==='register'): ?>Already part of Learnow? <a href="<?= e(route_url('/login')) ?>">Sign in</a><?php elseif($mode==='login'): ?>New around here? <a href="<?= e(route_url('/register')) ?>">Start learning free</a><?php else: ?>Remember your password? <a href="<?= e(route_url('/login')) ?>">Back to sign in</a><?php endif; ?></p>
<?php if($mode==='register'): ?><div class="auth-security-note"><?= icon('check-circle',13) ?> No card needed. No pressure. Just possibilities.</div><?php endif; ?>
